import * as React from "react";
import { MARK } from "./mark-geometry";
import type { Mark, MarkGeometry, MarkShape } from "./parse-mark";

/**
 * The brand mark, drawn from `assets/brand/mark.svg` (`mark-geometry.ts`,
 * generated by `scripts/brand-geometry.sh`). One component for every place
 * the console shows the logo, so a new mark is one SVG change plus
 * `scripts/render-brand.sh`.
 *
 * Ink shapes use `currentColor` and follow their container: the rail tile
 * follows the theme. Presence shapes (a two-colour mark's dot) use
 * `--hb-mark-dot`, by default `--hb-green`. Masks keep their gaps; their ids
 * are scoped per instance so several marks on one page never share one.
 */
export function BrandMark({
  label,
  mark = MARK,
  underlay,
  overlay,
  ...props
}: React.ComponentProps<"svg"> & {
  /** Accessible name; omit when the container already names it. */
  label?: string;
  /** Another geometry (tests, previews); defaults to the brand's. */
  mark?: Mark;
  /** Drawn under the mark's shapes (the living logo's wave). */
  underlay?: React.ReactNode;
  /** Drawn over the mark (the living logo's check and arc). */
  overlay?: React.ReactNode;
}) {
  const scope = React.useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const maskId = (id: string) => `hb-mark-${scope}-${id}`;
  return (
    <svg
      viewBox={mark.viewBox}
      fill="currentColor"
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true, focusable: false })}
      {...props}
    >
      {mark.masks.length > 0 ? (
        <defs>
          {mark.masks.map((m) => (
            <mask key={m.id} id={maskId(m.id)} maskUnits="userSpaceOnUse">
              {/* Mask luminance, not paint: white keeps, black cuts. */}
              {m.shapes.map((s, i) => shape(s, i, { fill: s.keep ? "white" : "black" }))}
            </mask>
          ))}
        </defs>
      ) : null}
      {underlay}
      {mark.shapes.map((s, i) =>
        shape(s, i, {
          className: s.tone === "presence" ? "hb-mk-dot" : "hb-mk-ink",
          ...(s.tone === "presence" ? { style: { fill: "var(--hb-mark-dot, var(--hb-green))" } } : {}),
          ...(s.mask ? { mask: `url(#${maskId(s.mask)})` } : {}),
        }),
      )}
      {overlay}
    </svg>
  );
}

function shape(s: MarkGeometry | MarkShape, key: number, extra: React.SVGProps<SVGElement>) {
  const common = extra as React.SVGProps<SVGPathElement & SVGCircleElement & SVGRectElement>;
  if (s.kind === "path") return <path key={key} d={s.d} fillRule={s.fillRule} {...common} />;
  if (s.kind === "circle") return <circle key={key} cx={s.cx} cy={s.cy} r={s.r} {...common} />;
  return <rect key={key} x={s.x} y={s.y} width={s.width} height={s.height} {...common} />;
}
